// TIGHT coupling: OrderService directly knows about EmailService implementation
class OrderService {
    private EmailService emailService = new EmailService(); // tightly coupled!
    void placeOrder(Order o) { emailService.sendConfirmation(o); }
}
// Changing EmailService to SMSService requires changing OrderService

// LOOSE coupling: OrderService depends on interface
class OrderService {
    private final NotificationService notifier; // depends on interface
    OrderService(NotificationService n) { this.notifier = n; }
    void placeOrder(Order o) { notifier.notify(o); }
}
// Swap EmailService for SMSService without touching OrderService

// Without interface: PaymentService is tightly coupled to StripePayment
class PaymentService {
    private StripePayment stripe = new StripePayment();
    void charge(double amount) { stripe.charge(amount); }
}
// Switching to PayPal requires changing PaymentService

// With interface: PaymentService knows nothing about Stripe or PayPal
interface PaymentGateway { void charge(double amount); }
class StripePayment implements PaymentGateway { ... }
class PayPalPayment implements PaymentGateway { ... }
class PaymentService {
    private final PaymentGateway gateway;
    PaymentService(PaymentGateway g) { this.gateway = g; }
    void charge(double amount) { gateway.charge(amount); }
}
